actions.script:
sessionId=null
def access=ec.service.sync().name('zenith.base.SecurityServices.check#ModuleWriteAccess').parameter('moduleId',ec.context.kitchenModuleId ?: 'pos').call()
def scope=ec.service.sync().name('zenith.pos.KotServices.get#BillingScope').parameter('terminalId',ec.context.terminalId).call()?.scope
if(!scope?.allowed) return
if(access.canWrite!=true) { ec.message.addError('KOT write access is required.'); return }
def counter=ec.entity.find('zenith.erp.pos.PosTerminal').condition('terminalId',ec.context.terminalId).forUpdate(true).one()
def shop=ec.service.sync().name('zenith.base.ShopServices.get#ActiveShopScope').call().activeShopId
if(counter?.isActive!='Y' || !counter.facilityId || (shop && counter.facilityId!=shop)) { ec.message.addError('Choose an active terminal in this shop.'); return }
if(ec.context.tableId) {
    def selected=ec.service.sync().name('zenith.pos.KotServices.resolve#KotTable').parameter('tableId',ec.context.tableId).call()?.table
    if(ec.message.hasError() || selected?.facilityId!=counter.facilityId) { ec.message.addError('Choose a terminal in the selected table’s shop.'); return }
}
def existing=ec.entity.find('zenith.erp.pos.PosSession').condition('terminalId',counter.terminalId).condition('statusId','PsOpen').one()
if(existing) {
    if(existing.operatorPartyId!=ec.user.userAccount?.partyId) { ec.message.addError('This terminal is in use by another cashier.'); return }
    sessionId=existing.sessionId
} else sessionId=ec.service.sync().name('zenith.pos.PosServices.open#PosSession')
    .parameters([terminalId:counter.terminalId,openingCash:ec.context.openingCash ?: '0']).call()?.sessionId

def billing=ec.service.sync().name('zenith.pos.KotServices.get#BillingSession').parameter('sessionId',sessionId).call()
def k=billing?.terminal ? ec.entity.find('zenith.erp.pos.KitchenOrderTicket').condition('kotId',kotId)
    .condition('organizationPartyId',billing.terminal.organizationPartyId).one() : null
def tx=k?.transactionId ? ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId',k.transactionId)
    .condition('organizationPartyId',k.organizationPartyId).condition('statusId','PtCompleted').one() : null
def issuedAt=tx ? ec.entity.find('zenith.erp.pos.PosSession').condition('sessionId',tx.sessionId).one() : null
def scope=tx ? ec.service.sync().name('zenith.pos.PosAccessServices.assert#PosAccess').parameter('transactionId',tx.transactionId).call() : null
if (!scope?.allowed || issuedAt?.terminalId!=billing.terminal?.terminalId || (k.terminalId && k.terminalId!=issuedAt.terminalId)) {
    ec.web.sendJsonResponse([success:false,error:'This bill is unavailable for the current terminal and login.']); return
}
def kitchenWrite=ec.service.sync().name('zenith.base.SecurityServices.check#ModuleWriteAccess')
    .parameter('moduleId',ec.context.kitchenModuleId ?: 'pos').call().canWrite
def posWrite=ec.service.sync().name('zenith.base.SecurityServices.check#ModuleWriteAccess').parameter('moduleId','pos').call().canWrite
// The audited amendment is submitted through POS Terminal.
def posInPlan=ec.user.isInGroup('ADMIN') || !ec.entity.isEntityDefined('zenith.erp.saas.SaasTenant') ||
    ec.service.sync().name('zenith.saas.SaasGateServices.check#ModuleAccess')
        .parameter('moduleId','pos').disableAuthz().call()?.allowed == true
def role=ec.service.sync().name('zenith.base.RoleAccessServices.get#AssignedRoleScope').disableAuthz().call()
def hasPosTerminal=!role.restricted || role.legacyWriteModules.contains('pos') || role.selections.pos?.contains('/pos/Terminal')
def lines=ec.entity.find('zenith.erp.pos.PosTransactionItem').condition('transactionId',tx.transactionId).orderBy('itemSeqId').list()
ec.web.sendJsonResponse([success:true,transactionId:tx.transactionId,number:tx.transactionNumber ?: tx.transactionId,
    total:tx.payableAmount ?: 0, salesModeId:tx.salesModeId, canEdit:kitchenWrite == true && posWrite == true && posInPlan && hasPosTerminal,
    items:lines.collect { [seq:it.itemSeqId, name:it.productName ?: it.productId, qty:it.quantity,
        rate:it.unitPrice, discountPercent:it.discountPercent, discountAmount:it.discountAmount,
        taxableAmount:it.taxableAmount, tax:it.totalTaxAmount ?: 0, total:it.lineTotal ?: 0] }])

def fail={ String reason -> ec.message.addError(reason); ec.web.sendJsonResponse([success:false,error:reason]) }
def sid=ec.context.sessionId
def access=ec.service.sync().name('zenith.base.SecurityServices.check#ModuleWriteAccess')
    .parameter('moduleId',ec.context.kitchenModuleId ?: 'pos').call()
if(!sid || access.canWrite!=true) { fail('KOT write access and an open session are required.'); return }
def billing=ec.service.sync().name('zenith.pos.KotServices.get#BillingSession').parameter('sessionId',sid).call()
if(ec.message.hasError() || !billing?.terminal) {
    ec.web.sendJsonResponse([success:false,error:ec.message.errorsString ?: 'Choose your open terminal session.']); return
}
if(ec.context.drawerAction=='close') {
    BigDecimal amount
    try { amount=new BigDecimal(ec.context.closingCash?.toString() ?: '') }
    catch(NumberFormatException ignored) { fail('Enter a valid closing cash amount.'); return }
    if(amount<0 || amount.scale()>2) { fail('Enter a non-negative closing cash amount with at most two decimals.'); return }
    try {
        ec.service.sync().name('zenith.pos.PosServices.close#PosSession').parameters([sessionId:sid,closingCash:amount]).call()
    } catch(Exception failure) {
        ec.transaction.setRollbackOnly('KOT session close failed',failure)
        if(!ec.message.hasError()) ec.message.addError('Session could not be closed. No changes were saved.')
    }
    ec.web.sendJsonResponse([success:!ec.message.hasError(),error:ec.message.errorsString]); return
}
def drawer=ec.service.sync().name('zenith.pos.PosServices.get#PosSessionCashSummary')
    .parameters([sessionId:sid,includeCheckoutSummary:true]).call()
ec.web.sendJsonResponse([success:!ec.message.hasError() && drawer?.checkoutSummary!=null,
    summary:drawer?.checkoutSummary,error:ec.message.errorsString])

def reply = { Map result = [:] ->
    if (ec.context.wantJson == 'Y') {
        ec.web.sendJsonResponse(result + [success:!!result,error:ec.message.errorsString])
    } else if (result) {
        ec.message.addMessage('KOT #' + result.kotNumber + ' sent to the kitchen.')
    }
}
def access = ec.service.sync().name('zenith.base.SecurityServices.check#ModuleWriteAccess')
    .parameter('moduleId', ec.context.kitchenModuleId ?: 'pos').call()
def scope=ec.service.sync().name('zenith.pos.PosAccessServices.assert#PosAccess').call()
org=scope.organizationPartyId
if (access?.canWrite != true || !scope.allowed) { ec.message.addError('POS write access and an active shop are required.'); return reply() }

def billing=ec.service.sync().name('zenith.pos.KotServices.get#BillingSession').parameter('sessionId',ec.context.sessionId).call()
if(ec.message.hasError() || !billing.terminal) return reply()
def display=ec.service.sync().name('zenith.pos.KotServices.get#KitchenDisplayPolicy').parameter('facilityId',billing.terminal.facilityId).call()
if(!display.enabled) { ec.message.addError('Kitchen Display is disabled for this shop. Use KOT printing instead of sending to the kitchen.'); return reply() }

def draft
def dId=ec.context.loadedDraftId
if (dId) {
    draft=ec.entity.find('zenith.erp.pos.KitchenOrderTicket').condition('kotId',dId).forUpdate(true).one()
    if (!draft || draft.statusId!='KotDraft' || draft.organizationPartyId!=org ||
        (!draft.terminalId && scope.terminalRestricted) || (draft.terminalId && draft.terminalId!=billing.terminal.terminalId)) {
        ec.message.addError('This draft is no longer available in this shop.'); return reply()
    }
}
def selected = ec.service.sync().name('zenith.pos.KotServices.resolve#KotTable')
    .parameters([tableId:ec.context.tableId,tableNumber:ec.context.tableNumber]).call()?.table
if (ec.message.hasError()) return reply()
if(ec.context.orderType=='Take Away') selected=null
if(selected) {
    selected=ec.entity.find('zenith.erp.pos.RestaurantTable').condition('tableId',selected.tableId).forUpdate(true).one()
    if(!selected || !(selected.statusId in [null,'TblAvailable','TblOccupied'])) { ec.message.addError('Choose an available or occupied table.'); return reply() }
}
def shop=ec.service.sync().name('zenith.base.ShopServices.get#ActiveShopScope').call().activeShopId
if(shop && selected && selected.facilityId!=shop) { ec.message.addError('Choose a table in the selected shop.'); return reply() }
if(selected && selected.facilityId!=billing.terminal.facilityId) { ec.message.addError('Choose a table at this terminal shop.'); return reply() }
def tableIdVal = ec.context.orderType == 'Take Away' ? null : selected?.tableId
def tableLabel = ec.context.orderType == 'Take Away' ? null : (selected?.tableNumber ?: ec.context.tableNumber)

def items = []
try { if (ec.context.itemsJson) items = new groovy.json.JsonSlurper().parseText(ec.context.itemsJson) } catch (e) { items = [] }
if (!(items instanceof List) || !items || items.size() > 100) { ec.message.addError('Choose 1 to 100 valid menu items.'); return reply() }
def checkedItems = []
for (def submitted in items) {
    def productId = submitted instanceof Map ? submitted.productId : null
    def product = productId ? ec.entity.find('mantle.product.Product').condition('productId', productId).one() : null
    BigDecimal quantity = null
    try { quantity = new BigDecimal(String.valueOf(submitted instanceof Map ? submitted.quantity : null)) } catch (ignored) { }
    if (!product || product.ownerPartyId != org || product.productTypeEnumId != 'PtAsset' || quantity == null || quantity <= 0) {
        ec.message.addError('The KOT contains an invalid item or quantity. Refresh the menu and try again.'); return reply()
    }
    checkedItems.add([productId:product.productId, productName:(product.productName ?: product.productId),
                      quantity:quantity, specialInstructions:submitted.specialInstructions])
}
def quote=ec.service.sync().name('zenith.pos.KitchenPrintServices.get#CartReceipt')
    .parameters([sessionId:ec.context.sessionId,itemsJson:ec.context.itemsJson,tableId:tableIdVal,orderType:ec.context.orderType,taxOn:ec.context.taxOn ?: 'Y',salesModeId:ec.context.salesModeId,waiterId:ec.context.waiterId,customerPartyId:ec.context.customerPartyId,notes:ec.context.notes,lockDiscountMode:true]).call()?.receipt
if(ec.message.hasError()) return reply()
def nextNum = ec.service.sync().name('zenith.pos.KotServices.next#KotNumber').call()?.kotNumber
if (!nextNum) return reply()
quote.bill.number='KOT #'+nextNum
def orderReceipt=groovy.json.JsonOutput.toJson(quote)

def notesVal = (ec.context.orderType ? ('[' + ec.context.orderType + '] ') : '') + (ec.context.notes ?: '')
def kr = ec.service.sync().name('create#zenith.erp.pos.KitchenOrderTicket')
    .parameters([organizationPartyId:org, terminalId:billing.terminal.terminalId, kotNumber:String.valueOf(nextNum),
                 tableId:tableIdVal, tableNumber:tableLabel, waiterName:quote.bill.waiter, orderReceiptJson:orderReceipt, statusId:'KotNew', printCount:0,
                 kotDate:ec.user.nowTimestamp, notes:notesVal]).call()
def newKotId = kr.kotId
def seq = 0
checkedItems.each { it2 ->
    seq++
    ec.service.sync().name('create#zenith.erp.pos.KotItem')
        .parameters([kotId:newKotId, kotItemSeqId:String.format('%05d', seq),
                     productId:it2.productId, productName:it2.productName,
                     quantity:((it2.quantity ?: 1) as BigDecimal),
                     specialInstructions:it2.specialInstructions]).call()
}
if (tableIdVal && !ec.message.hasError()) selected.set('statusId','TblOccupied').update()
// if this order was resumed from a saved draft, remove the draft (it has become live)
if (draft) {
    ec.entity.find('zenith.erp.pos.KotItem').condition('kotId', dId).deleteAll()
    draft.delete()
}
reply(ec.message.hasError() ? [:] : [kotId:newKotId,kotNumber:nextNum])

def reply = { Map result = [:] ->
    if (ec.context.wantJson == 'Y')
        ec.web.sendJsonResponse(result + [success:!!result,error:ec.message.errorsString])
}
def access = ec.service.sync().name('zenith.base.SecurityServices.check#ModuleWriteAccess')
    .parameter('moduleId', ec.context.kitchenModuleId ?: 'pos').call()
def scope=ec.service.sync().name('zenith.pos.PosAccessServices.assert#PosAccess').call()
org=scope.organizationPartyId
if (access?.canWrite != true || !scope.allowed) { ec.message.addError('Write access and an active shop are required.'); return reply() }

def offlineDraftId = ec.context.offlineDraftId
if (offlineDraftId) {
    if (ec.context.kitchenModuleId != 'kot' || ec.context.wantJson != 'Y' ||
        ec.context.existingDraftId || !(offlineDraftId ==~ /[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}/) ||
        ec.context.offlineOrganizationId != org || ec.context.offlineUserId != ec.user.userId) {
        ec.message.addError('Sign in to the original organization, account and counter to sync this draft.')
        return reply()
    }
    // Serialize import retries and use the same tenant lock as KOT capacity changes.
    def tenant = ec.entity.isEntityDefined('zenith.erp.saas.SaasTenant') ?
        ec.entity.find('zenith.erp.saas.SaasTenant').condition('organizationPartyId',org).disableAuthz().forUpdate(true).one() : null
    if (!tenant && !ec.entity.find('mantle.party.Organization').condition('partyId',org).forUpdate(true).one()) {
        ec.message.addError('Choose an active organization before syncing.')
        return reply()
    }
}

def billing=ec.service.sync().name('zenith.pos.KotServices.get#BillingSession').parameter('sessionId',ec.context.sessionId).call()
if(ec.message.hasError() || !billing.terminal) return reply()
def offlineKey
if (offlineDraftId) {
    if (ec.context.offlineTerminalId != billing.terminal.terminalId) {
        ec.message.addError('Open the original counter to sync this draft.')
        return reply()
    }
    offlineKey = [organizationPartyId:org, terminalId:billing.terminal.terminalId,
                  userId:ec.user.userId, offlineDraftId:offlineDraftId]
    def prior = ec.entity.find('zenith.erp.pos.KotOfflineDraftSync').condition(offlineKey).one()
    if (prior) return reply([offlineDraftId:offlineDraftId,kotId:prior.kotId,kotNumber:prior.kotNumber])
}

def draft
def exId=ec.context.existingDraftId
if (exId) {
    draft=ec.entity.find('zenith.erp.pos.KitchenOrderTicket').condition('kotId',exId).forUpdate(true).one()
    if (!draft || draft.statusId!='KotDraft' || draft.organizationPartyId!=org ||
        (!draft.terminalId && scope.terminalRestricted) || (draft.terminalId && draft.terminalId!=billing.terminal.terminalId)) {
        ec.message.addError('This draft is no longer available in this shop.'); return reply()
    }
}
def selected = ec.service.sync().name('zenith.pos.KotServices.resolve#KotTable')
    .parameters([tableId:ec.context.tableId,tableNumber:ec.context.tableNumber]).call()?.table
if (ec.message.hasError()) return reply()
if(ec.context.orderType=='Take Away') selected=null
if(selected) {
    selected=ec.entity.find('zenith.erp.pos.RestaurantTable').condition('tableId',selected.tableId).forUpdate(true).one()
    if(!selected || !(selected.statusId in [null,'TblAvailable','TblOccupied'])) { ec.message.addError('Choose an available or occupied table.'); return reply() }
}
def shop=ec.service.sync().name('zenith.base.ShopServices.get#ActiveShopScope').call().activeShopId
if(shop && selected && selected.facilityId!=shop) { ec.message.addError('Choose a table in the selected shop.'); return reply() }
if(selected && selected.facilityId!=billing.terminal.facilityId) { ec.message.addError('Choose a table at this terminal shop.'); return reply() }
def tableIdVal = ec.context.orderType == 'Take Away' ? null : selected?.tableId
def tableLabel = ec.context.orderType == 'Take Away' ? null : (selected?.tableNumber ?: ec.context.tableNumber)

def items = []
try { if (ec.context.itemsJson) items = new groovy.json.JsonSlurper().parseText(ec.context.itemsJson) } catch (e) { items = [] }
if (!(items instanceof List) || !items || items.size() > 100) { ec.message.addError('Choose 1 to 100 valid menu items before saving.'); return reply() }
def checkedItems = []
for (def submitted in items) {
    def productId = submitted instanceof Map ? submitted.productId : null
    def product = productId ? ec.entity.find('mantle.product.Product').condition('productId', productId).one() : null
    BigDecimal quantity = null
    try { quantity = new BigDecimal(String.valueOf(submitted instanceof Map ? submitted.quantity : null)) } catch (ignored) { }
    if (!product || product.ownerPartyId != org || product.productTypeEnumId != 'PtAsset' || quantity == null || quantity <= 0) {
        ec.message.addError('The draft contains an invalid item or quantity. Refresh the menu and try again.'); return reply()
    }
    checkedItems.add([productId:product.productId, productName:(product.productName ?: product.productId),
                      quantity:quantity, specialInstructions:submitted.specialInstructions])
}

// replacing a resumed draft => delete the old one first
def draftReceipt=ec.service.sync().name('zenith.pos.KitchenPrintServices.get#CartReceipt')
    .parameters([sessionId:ec.context.sessionId,itemsJson:ec.context.itemsJson,tableId:tableIdVal,orderType:ec.context.orderType,
                 taxOn:ec.context.taxOn ?: 'Y',salesModeId:ec.context.salesModeId,waiterId:ec.context.waiterId,customerPartyId:ec.context.customerPartyId,notes:ec.context.notes,lockDiscountMode:true,allowUnpricedDraft:true]).call()?.receipt
if(ec.message.hasError()) return reply()
if (ec.context.billingView in ['grid', 'list']) draftReceipt.billingView = ec.context.billingView
if (draft) {
    ec.entity.find('zenith.erp.pos.KotItem').condition('kotId', exId).deleteAll()
    draft.delete()
}

def nextNum = ec.service.sync().name('zenith.pos.KotServices.next#KotNumber').call()?.kotNumber
if (!nextNum) return reply()

def notesVal = (ec.context.orderType ? ('[' + ec.context.orderType + '] ') : '') + (ec.context.notes ?: '')
def kr = ec.service.sync().name('create#zenith.erp.pos.KitchenOrderTicket')
    .parameters([organizationPartyId:org, terminalId:billing.terminal.terminalId, kotNumber:String.valueOf(nextNum),
                 tableId:tableIdVal, tableNumber:tableLabel, waiterName:draftReceipt.bill.waiter, orderReceiptJson:groovy.json.JsonOutput.toJson(draftReceipt), statusId:'KotDraft', printCount:0,
                 kotDate:ec.user.nowTimestamp, notes:notesVal]).call()
def newKotId = kr.kotId
if (ec.message.hasError() || !newKotId) return reply()
def seq = 0
checkedItems.each { it2 ->
    seq++
    ec.service.sync().name('create#zenith.erp.pos.KotItem')
        .parameters([kotId:newKotId, kotItemSeqId:String.format('%05d', seq),
                     productId:it2.productId, productName:it2.productName,
                     quantity:((it2.quantity ?: 1) as BigDecimal),
                     specialInstructions:it2.specialInstructions]).call()
}
def display=ec.service.sync().name('zenith.pos.KotServices.get#KitchenDisplayPolicy').parameter('facilityId',billing.terminal.facilityId).call()
if(selected && !display.enabled && !ec.message.hasError()) selected.set('statusId','TblOccupied').update()
if (ec.message.hasError()) return reply()
if (offlineKey) {
    ec.entity.makeValue('zenith.erp.pos.KotOfflineDraftSync')
        .setAll(offlineKey + [kotId:newKotId,kotNumber:nextNum,syncedDate:ec.user.nowTimestamp]).create()
}
if(ec.context.wantJson=='Y') {
    def revision=ec.entity.find('zenith.erp.pos.KitchenOrderTicket').condition('kotId',newKotId).one()?.lastUpdatedStamp?.time
    reply([kotId:newKotId,kotNumber:nextNum,total:draftReceipt.summary.total,offlineDraftId:offlineDraftId,sourceRevision:revision?.toString()])
}
else ec.message.addMessage('Saved as Draft #' + nextNum + '.')

def access = ec.service.sync().name('zenith.base.SecurityServices.check#ModuleWriteAccess')
    .parameter('moduleId', 'kot').call()
def draftId = ec.context.offlineDraftId
if (ec.context.kitchenModuleId != 'kot' || access?.canWrite != true ||
    !(draftId ==~ /[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}/) || ec.context.offlineUserId != ec.user.userId) {
    ec.web.sendJsonResponse([success:false,error:'Sign in to the original counter to confirm the draft.']); return
}
def billing = ec.service.sync().name('zenith.pos.KotServices.get#BillingSession')
    .parameter('sessionId',ec.context.sessionId).call()
if (ec.message.hasError() || !billing.terminal || ec.context.offlineOrganizationId != billing.terminal.organizationPartyId ||
    ec.context.offlineTerminalId != billing.terminal.terminalId) {
    ec.web.sendJsonResponse([success:false,error:ec.message.errorsString ?: 'Open the original counter to confirm the draft.']); return
}
def receipt = ec.entity.find('zenith.erp.pos.KotOfflineDraftSync').condition([organizationPartyId:billing.terminal.organizationPartyId,
    terminalId:billing.terminal.terminalId,userId:ec.user.userId,offlineDraftId:draftId]).one()
ec.web.sendJsonResponse([success:!!receipt,offlineDraftId:receipt?.offlineDraftId,kotId:receipt?.kotId,kotNumber:receipt?.kotNumber,
    error:receipt ? null : 'The draft has not been confirmed. Retry when connected.'])

def access = ec.service.sync().name('zenith.base.SecurityServices.check#ModuleWriteAccess')
    .parameter('moduleId', ec.context.kitchenModuleId ?: 'pos').call()
def scope=ec.service.sync().name('zenith.pos.PosAccessServices.assert#PosAccess').call()
org=scope.organizationPartyId
if (access?.canWrite != true || !scope.allowed) { ec.message.addError('POS write access and an active shop are required.'); return }
def k = ec.entity.find('zenith.erp.pos.KitchenOrderTicket').condition('kotId', ec.context.kotId).one()
if (k && k.statusId == 'KotDraft' && k.organizationPartyId == org) {
    def selected=ec.service.sync().name('zenith.pos.KotServices.get#BillingSession').parameter('sessionId',ec.context.sessionId).call()
    if(!selected.terminal || (!k.terminalId && scope.terminalRestricted) || (k.terminalId && k.terminalId!=selected.terminal.terminalId)) { ec.message.addError('Choose the terminal that holds this order.'); return }
    ec.entity.find('zenith.erp.pos.KotItem').condition('kotId', ec.context.kotId).deleteAll()
    def tableId=k.tableId
    k.delete()
    if(tableId) {
        def table=ec.entity.find('zenith.erp.pos.RestaurantTable').condition('tableId',tableId).forUpdate(true).one()
        def remaining=ec.entity.find('zenith.erp.pos.KitchenOrderTicket').condition('organizationPartyId',org).condition('tableId',tableId)
            .condition('statusId','in',['KotDraft','KotNew','KotPreparing','KotReady']).count()
        if(table && !remaining && !table.currentTransactionId && table.statusId=='TblOccupied') table.set('statusId','TblAvailable').update()
    }
}

def billing=ec.service.sync().name('zenith.pos.KotServices.get#BillingSession').parameter('sessionId',ec.context.sessionId).call()
if(!billing.terminal || ec.message.hasError()) { ec.web.sendJsonResponse([success:false,customers:[]]); return }
def orgId=billing.terminal.organizationPartyId
def term=(ec.context.term ?: '').toString().trim(), termL=term.toLowerCase()
def out=[]
try {
    def rows=ec.entity.find('mantle.party.PartyDetailAndRole')
        .condition('roleTypeId','in',['Customer','CustomerBillTo']).condition('ownerPartyId',orgId)
        .orderBy('organizationName,firstName,lastName').limit(1000).list()
    def nameOf={ r -> (r.organizationName ?: (((r.firstName ?: '')+' '+(r.lastName ?: '')).trim())) ?: r.partyId }
    def custIds=rows.collect { it.partyId }.unique()
    def pid2phone=[:]
    if(custIds) {
        def pcms=ec.entity.find('mantle.party.contact.PartyContactMech').condition('partyId','in',custIds)
            .conditionDate('fromDate','thruDate',ec.user.nowTimestamp).list()
        def cmIds=pcms.collect { it.contactMechId }.unique()
        def cm2num=[:]
        if(cmIds) ec.entity.find('mantle.party.contact.TelecomNumber').condition('contactMechId','in',cmIds).list().each { tn ->
            cm2num[tn.contactMechId]=((tn.countryCode ? ('+'+tn.countryCode+' ') : '')+(tn.areaCode ?: '')+' '+(tn.contactNumber ?: '')).replaceAll('\\s+',' ').trim()
        }
        pcms.each { pcm -> def n=cm2num[pcm.contactMechId]; if(n && !pid2phone[pcm.partyId]) pid2phone[pcm.partyId]=n }
    }
    def digits=term.replaceAll('[^0-9]','')
    def seen=[:]
    for(r in rows) {
        if(seen[r.partyId]) continue
        def nm=nameOf(r), phone=pid2phone[r.partyId] ?: ''
        def phoneDigits=phone.replaceAll('[^0-9]','')
        def match=!term || nm.toLowerCase().contains(termL) || (r.partyId ?: '').toLowerCase().contains(termL) || (digits.length()>=3 && phoneDigits.contains(digits))
        if(!match) continue
        seen[r.partyId]=true
        out.add([id:r.partyId,name:nm,phone:phone])
        if(out.size()>=30) break
    }
    def terms=out ? ec.entity.find('mantle.party.Party').condition('partyId','in',out*.id)
        .list().collectEntries { [(it.partyId):it.creditDays] } : [:]
    out.each { it.creditDays=terms[it.id] }
    ec.web.sendJsonResponse([success:true,customers:out])
} catch(Exception e) { ec.web.sendJsonResponse([success:false,customers:[]]) }

def scope=ec.service.sync().name('zenith.pos.PosAccessServices.assert#PosAccess').call()
def result=[success:false,products:[]]
if(scope.allowed) {
    def term=(ec.context.term ?: '').toString().take(100)
    def rawOffset=(ec.context.offset ?: '0').toString()
    def offset=rawOffset ==~ /[0-9]{1,4}/ ? Math.min(rawOffset.toInteger(),3000) : 0
    def scan
    def found
    if(term.trim()) {
        if(!offset) scan=ec.service.sync().name('zenith.barcode.BarcodeServices.resolve#ScanProduct').parameter('code',term).call()
        found=ec.service.sync().name('zenith.pos.PosCheckoutServices.search#PosProducts')
            .parameters([term:term,offset:offset,pageSize:41]).call()?.products ?: []
    } else {
        def products=ec.entity.find('mantle.product.Product')
            .condition([ownerPartyId:scope.organizationPartyId,productTypeEnumId:'PtAsset'])
            .conditionDate('salesIntroductionDate','salesDiscontinuationDate',ec.user.nowTimestamp)
        def categoryId=ec.context.categoryId
        if(categoryId) {
            def category=ec.entity.find('mantle.product.category.ProductCategory')
                .condition([productCategoryId:categoryId,ownerPartyId:scope.organizationPartyId]).one()
            def members=category ? ec.entity.find('mantle.product.category.ProductCategoryMember')
                .condition('productCategoryId',categoryId).conditionDate('fromDate','thruDate',ec.user.nowTimestamp)
                .selectField('productId').list()*.productId : []
            found=members ? products.condition('productId',org.moqui.entity.EntityCondition.IN,members)
                .orderBy('productName,productId').offset(offset).limit(41).list() : []
        } else found=products.orderBy('productName,productId').offset(offset).limit(41).list()
    }
    def hasMore=found.size()>40 && offset<3000
    def page=found.take(40)
    def exact
    if(scan?.found) {
        exact=page.find { it.productId==scan.productId }
        if(!exact) {
            exact=ec.entity.find('mantle.product.Product').condition('productId',scan.productId)
                .condition('ownerPartyId',scope.organizationPartyId).condition('productTypeEnumId','PtAsset').one()
            // A scan is an additional exact match. Keep the entire page for subsequent paging.
            if(exact) page=[exact]+page
        }
    }
    def stock=[:]
    def sid=ec.context.stockSessionId
    def authorizedSession=sid ? ec.entity.find('zenith.erp.pos.PosSession').condition('sessionId',sid)
        .condition('operatorPartyId',ec.user.userAccount?.partyId).condition('organizationPartyId',scope.organizationPartyId)
        .condition('statusId','PsOpen').one() : null
    if(authorizedSession && page) stock=ec.service.sync().name('zenith.pos.PosCheckoutServices.get#PosCardStock')
        .parameters([sessionId:sid,productIds:page*.productId]).call()?.stock ?: [:]
    def modeId=ec.context.salesModeId
    def mode=modeId ? ec.entity.find('zenith.erp.pos.PosSalesMode').condition([salesModeId:modeId,isActive:'Y']).one() : null
    def validMode=!modeId || (mode && (!mode.organizationPartyId || mode.organizationPartyId==scope.organizationPartyId))
    def overrides=[:]
    if(validMode && modeId && page) overrides=ec.service.sync()
        .name('zenith.pos.ProductModePricingServices.get#ModePriceOverrides')
        .parameters([salesModeId:modeId,productIds:page*.productId]).disableAuthz().call().overrides ?: [:]
    result=[success:!ec.message.hasError(),exactId:exact?.productId,ambiguous:scan?.ambiguous,hasMore:hasMore,
        products:page.collect { p ->
            def price=validMode ? (overrides.containsKey(p.productId) ? overrides[p.productId] : p.mrpAmount) : null
            def reason=!validMode ? 'This sales mode is not available for this product.' : null
            [id:p.productId,name:p.productName ?: p.productId,code:p.pseudoId ?: p.productId,
             price:validMode ? (price ?: 0) : null,pricePending:validMode && price==null,reason:reason,stock:stock[p.productId]?.quantity]
        }]
}
ec.web.sendJsonResponse(result)

def sale
try { sale=new groovy.json.JsonSlurper().parseText(ec.context.saleJson as String) } catch (Exception ignored) { }
if (!(sale instanceof Map)) { ec.web.sendJsonResponse([success:false,error:'Invalid offline order.']); return }
def synced=ec.service.sync().name('zenith.pos.KotOfflineServices.import#KotSale')
    .parameters([sessionId:ec.context.sessionId,sale:sale]).call()?.syncedOrder
ec.web.sendJsonResponse(synced ?: [success:false,error:ec.message.errorsString ?: 'Could not sync this KOT order.'])

import org.moqui.entity.EntityCondition
import groovy.json.JsonOutput
def scope=ec.service.sync().name('zenith.pos.KotServices.get#BillingScope').call()?.scope ?: [:]
org=scope.allowed ? scope.organizationPartyId : null
kotCounterNeedsSetup=scope.kotCounterConfigured == false
def IN=EntityCondition.ComparisonOperator.IN
def cf=ec.entity.conditionFactory
billingSession=null; billingTerminal=null
entryTerminals=[]
if(!org) return
if(ec.context.sessionId) {
    def billing=ec.service.sync().name('zenith.pos.KotServices.get#BillingSession')
        .parameters([sessionId:ec.context.sessionId,includeBillSummary:true]).call()
    if(!billing?.session || !billing?.terminal) {
        kotSessionUnavailable=true
        return
    }
    billingSession=billing.session; billingTerminal=billing.terminal
    lastCompleted=billing.billSummary?.lastCompleted
    todayBillCount=billing.billSummary?.todayBillCount
    latestIssuedBillNo=billing.billSummary?.latestIssuedBillNo
}
if(!billingSession) {
    def shopScope=ec.service.sync().name('zenith.base.ShopServices.get#ActiveShopScope').call()
    if(shopScope==null || ec.message.hasError()) return
    def shop=shopScope.activeShopId
    def terminals=ec.entity.find('zenith.erp.pos.PosTerminal').condition('organizationPartyId',org).condition('isActive','Y')
    if(shop) terminals.condition('facilityId',shop)
    entryTerminals=terminals.list().findAll { !scope.terminalRestricted || it.terminalId in (scope.allowedTerminalIds ?: []) }
    return
}
def shop=billingTerminal.facilityId
kitchenDisplayEnabled=ec.service.sync().name('zenith.pos.KotServices.get#KitchenDisplayPolicy').parameter('facilityId',shop).call().enabled
modes=ec.service.sync().name('zenith.pos.PosModeServices.get#TerminalModes').parameter('terminalId',billingTerminal.terminalId).call().modes ?: []
waiters=org ? ec.entity.find('zenith.erp.pos.Waiter').condition('organizationPartyId',org).condition('isActive','Y').orderBy('waiterName').list() : []
gridCategories=org ? ec.entity.find('mantle.product.category.ProductCategory').condition('ownerPartyId',org)
    .orderBy('categoryName,productCategoryId').limit(60).list() : []
// BillingSession already validates ownership of the terminal's shop.
tables=ec.entity.find('zenith.erp.pos.RestaurantTable')
    .condition('facilityId',shop).orderBy('tableNumber').limit(200).list()
tableLabelsJson=JsonOutput.toJson(tables.collectEntries { [(it.tableId):it.tableNumber ?: it.tableId] })

def kotLabel = { st ->
    if (st == 'KotNew') return 'Pending'
    if (st == 'KotPreparing') return 'In Kitchen'
    if (st == 'KotReady') return 'Ready'
    if (st == 'KotServed') return 'Served'
    if (st == 'KotCancelled') return 'Cancelled'
    if (st == 'KotDraft') return 'Draft'
    return st
}
def kotBadge = { st ->
    if (st == 'KotNew') return 'orange'
    if (st == 'KotPreparing' || st == 'KotReady') return 'green'
    return 'grey'
}
def loadKots = { statuses, lim ->
    def f = ec.entity.find('zenith.erp.pos.KitchenOrderTicket').condition('statusId', IN, statuses)
    f.condition('organizationPartyId', org ?: '__NO_ORGANIZATION__')
    if(billingTerminal) f.condition(cf.makeCondition([cf.makeCondition('terminalId',EntityCondition.ComparisonOperator.EQUALS,billingTerminal.terminalId),
        cf.makeCondition('terminalId',EntityCondition.ComparisonOperator.EQUALS,null)],EntityCondition.JoinOperator.OR))
    if(lim) f.limit(lim)
    def ks = f.orderBy('-kotDate').list()
    // Pre-terminal drafts remain recoverable by an owner. Never expose an
    // unattributed legacy order to a restricted cashier or another shop's table.
    if(billingTerminal) ks=ks.findAll { k ->
        if(k.terminalId) return true
        if(scope.terminalRestricted) return false
        if(k.transactionId) {
            def tx=ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId',k.transactionId).one()
            def ss=tx ? ec.entity.find('zenith.erp.pos.PosSession').condition('sessionId',tx.sessionId).one() : null
            return ss?.terminalId==billingTerminal.terminalId
        }
        return !k.tableId || ec.entity.find('zenith.erp.pos.RestaurantTable').condition('tableId',k.tableId).one()?.facilityId==billingTerminal.facilityId
    }
    if (!ks) return []
    def kids = ks.collect { it.kotId }
    def its = ec.entity.find('zenith.erp.pos.KotItem').condition('kotId', IN, kids).orderBy('kotId,kotItemSeqId').list()
    def byKot = [:]
    its.each { i ->
        def lst = byKot[i.kotId]; if (lst == null) { lst = []; byKot[i.kotId] = lst }
        lst.add([ name:(i.productName ?: i.productId), qty:(((i.quantity ?: 1) as BigDecimal).stripTrailingZeros().toPlainString()) ])
    }
    def bills=ks*.transactionId.findAll { it }
    def issued=bills ? ec.entity.find('zenith.erp.pos.PosTransaction').condition('organizationPartyId',org)
        .condition('transactionId',IN,bills).condition('statusId','PtCompleted').list().collectEntries { [it.transactionId,it] } : [:]
    def methods=issued ? ec.entity.find('zenith.erp.pos.PosPayment').condition('transactionId',IN,issued.keySet())
        .selectFields(['transactionId','paymentMethod']).list().groupBy { it.transactionId } : [:]
    return ks.collect { k ->
        def snapshot=[:]
        if(k.orderReceiptJson) {
            try { snapshot=new groovy.json.JsonSlurper().parseText(k.orderReceiptJson) ?: [:] } catch(Exception ignored) { }
        }
        def issuedBill=issued[k.transactionId]
        def date=issuedBill?.completedDate ?: k.kotDate
        [ billNumber:issuedBill ? (issuedBill.transactionNumber ?: issuedBill.transactionId) : '',
          total:issuedBill ? issuedBill.payableAmount : snapshot?.summary?.total,
          customer:issuedBill?.customerName ?: snapshot?.bill?.customer ?: 'Walk-in',
          customerPartyId:snapshot?.bill?.customerPartyId ?: '', customerPhone:snapshot?.bill?.customerPhone ?: '',
          payment:(methods[k.transactionId] ?: [])*.paymentMethod.findAll { it }.unique().join(', '),
          searchText:([k.kotNumber,k.kotId,k.waiterName,issuedBill ? issuedBill.payableAmount : snapshot?.summary?.total] +
              (byKot[k.kotId] ?: [])*.name).findAll { it != null }.join(' '),
          sortedAt:date?.time ?: 0L,
          mode:modes.find { it.salesModeId==snapshot?.bill?.salesModeId }?.modeName ?: snapshot?.bill?.salesModeId ?: '',
          id:k.kotId, num:(k.kotNumber ?: k.kotId), table:(k.tableNumber ?: '-'),
        isoDate:(date ? ec.l10n.format(date, 'yyyy-MM-dd') : ''), time:(date ? ec.l10n.format(date, 'dd/MM/yyyy hh:mm a') : ''), waiter:k.waiterName ?: '', serviceType:(k.notes ?: '').startsWith('[Take Away]') ? 'Take Away' : 'Dine In',
          label:kotLabel(k.statusId), hasBill:!!(issuedBill || k.orderReceiptJson),
          canBill:!k.transactionId && (k.statusId in ['KotNew','KotPreparing','KotReady','KotServed']) && snapshot?.summary?.total!=null,
          items:(byKot[k.kotId] ?: []) ] }
}

includeBillingHistory = ec.web.parameters.loadHistory == 'Y'
if(includeBillingHistory) {
    def activeKots = loadKots(['KotNew', 'KotPreparing', 'KotReady'], 60)
    def completedKots = loadKots(['KotServed', 'KotCancelled'], 60)
    def draftKots = loadKots(['KotDraft'], null)
    historyKots=(draftKots.collect { it + [group:'draft'] } + activeKots.collect { it + [group:'active'] } +
        completedKots.collect { it + [group:'completed'] }).sort { a,b ->
        ((b.billNumber ? 1 : 0) <=> (a.billNumber ? 1 : 0)) ?: (b.sortedAt <=> a.sortedAt) ?: (b.id <=> a.id)
    }
}


// resume a draft into the cart?
loadedDraftId = ec.context.loadDraft ?: ''
def draftLoadItems = []
selectedTableId = ''
if (ec.context.tableId) {
    def selected = ec.service.sync().name('zenith.pos.KotServices.resolve#KotTable').parameters([tableId:ec.context.tableId]).call()?.table
    if (selected && selected.facilityId == shop) selectedTableId = selected.tableId
}
draftLoadTable = ''; draftLoadType = ''; draftLoadInstr = ''; draftLoadTax = 'Y'; draftLoadMode = ''; draftLoadWaiter = ''; draftReceiptLines = []
draftCustomer = [:]; draftRevision = ''; draftLoadView = 'list'
if (loadedDraftId) {
    def dk = ec.entity.find('zenith.erp.pos.KitchenOrderTicket').condition('kotId', loadedDraftId).one()
    if (billingTerminal && dk && dk.statusId == 'KotDraft' && org && dk.organizationPartyId == org && ((!dk.terminalId && !scope.terminalRestricted) || dk.terminalId==billingTerminal.terminalId)) {
        draftRevision = dk.lastUpdatedStamp?.time?.toString() ?: ''
        def dits = ec.entity.find('zenith.erp.pos.KotItem').condition('kotId', loadedDraftId).orderBy('kotItemSeqId').list()
        draftLoadItems = dits.collect { [ productId:it.productId, productName:it.productName,
            quantity:(((it.quantity ?: 1) as BigDecimal).stripTrailingZeros().toPlainString()) ] }
        draftLoadTable = dk.tableId ?: (tables.findAll { it.tableNumber == dk.tableNumber }.size() == 1 ? tables.find { it.tableNumber == dk.tableNumber }.tableId : '')
        def nt = dk.notes ?: ''
        def mm = (nt =~ /^\[([^\]]*)\]\s?(.*)$/)
        if (mm.find()) { draftLoadType = mm.group(1); draftLoadInstr = mm.group(2) } else { draftLoadInstr = nt }
        if (dk.orderReceiptJson) {
            try {
                def savedReceipt = new groovy.json.JsonSlurper().parseText(dk.orderReceiptJson)
                draftLoadTax = savedReceipt?.bill?.taxOn == 'N' ? 'N' : 'Y'
                draftLoadMode = savedReceipt?.bill?.salesModeId ?: ''
                draftLoadWaiter = savedReceipt?.bill?.waiterId ?: ''
                if (savedReceipt?.billingView == 'grid') draftLoadView = 'grid'
                draftReceiptLines = savedReceipt?.items ?: []
                def bill=savedReceipt?.bill
                if(bill?.customerPartyId) draftCustomer=[id:bill.customerPartyId,name:bill.customer,phone:bill.customerPhone]
            } catch (ignored) { }
        }
    } else { loadedDraftId = '' }
}

draftLoadJson = JsonOutput.toJson(draftLoadItems)
draftReceiptLinesJson = JsonOutput.toJson(draftReceiptLines)
draftCustomerJson = JsonOutput.toJson(draftCustomer)
draftModeUnavailable = draftLoadMode && !modes.any { it.salesModeId == draftLoadMode }
